 void load(){items.clear();items.add(new Item("vibe","\u547c\u5438\u71c8",asset("breath.png"),null));items.add(new Item("settings","\u8a2d\u5b9a",asset("settings.png"),null));items.add(new Item("voice","\u8a9e\u97f3\u8fa8\u8b58",new VoiceIcon(asset("voice.png")),new ComponentName("org.ev6.voicewindow","org.ev6.voicewindow.MainActivity")));try{JSONArray order=new JSONArray(prefs.getString("order","[]"));ArrayList<Item> sorted=new ArrayList<Item>();for(int j=0;j<order.length();j++){String id=order.getString(j);for(Item it:items)if(id.equals(it.id)&&!sorted.contains(it))sorted.add(it);}for(Item it:items)if(!sorted.contains(it))sorted.add(it);items=sorted;}catch(Exception ignored){}}
