 void content(View view){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff101012);root.setPadding(0,Math.round(90f*getResources().getDisplayMetrics().widthPixels/1920f),0,0);root.addView(view,new FrameLayout.LayoutParams(-1,-1));setContentView(root);}
