 LinearLayout page(String title){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(36,0,36,18);box.setBackgroundColor(0xff101012);TextView head=text("‹   "+title,25);head.setPadding(8,0,8,0);box.addView(head,new LinearLayout.LayoutParams(-1,86));head.setOnClickListener(new View.OnClickListener(){public void onClick(View v){onBackPressed();}});View line=new View(this);line.setBackgroundColor(0xff33333b);box.addView(line,new LinearLayout.LayoutParams(-1,1));content(box);return box;}
 void settings(){panelGeneration++;screen=1;LinearLayout b=page("\u8a2d\u5b9a");addRow(b,"\u547c\u5438\u71c8",new Runnable(){public void run(){panel("vibe");}});addRow(b,"ADB",new Runnable(){public void run(){adbPanel();}});addRow(b,"Launchpad",new Runnable(){public void run(){panel("pad");}});addRow(b,"\u8a9e\u97f3\u8fa8\u8b58",new Runnable(){public void run(){panel("voice");}});}

