 void optionsEnabled(boolean enabled){if(autoBoot==null)return;autoBoot.setEnabled(enabled);periodBar.setEnabled(enabled);for(int i=0;i<colorMode.getChildCount();i++)colorMode.getChildAt(i).setEnabled(enabled);}
 void bindOptions(String json){if(autoBoot==null)return;try{JSONObject value=new JSONObject(json);bindingOptions=true;autoBoot.setChecked(value.optBoolean("autoboot",true));String m=value.optString("mode","clockwise");colorMode.check("random".equals(m)?102:"counterclockwise".equals(m)?101:100);periodBar.setProgress(Math.max(0,value.optInt("period_ms",8000)/1000-2));optionsEnabled(!optionsBusy&&!busy);}catch(Exception e){diagnostic.setText("\u8a2d\u5b9a\u8b80\u53d6\u5931\u6557："+e.getMessage());}finally{bindingOptions=false;}}
 void saveBreathOptions(){if(bindingOptions||optionsBusy||busy||autoBoot==null)return;final int generation=panelGeneration;String m=colorMode.getCheckedRadioButtonId()==102?"random":colorMode.getCheckedRadioButtonId()==101?"counterclockwise":"clockwise";final String action="vibe-config:"+autoBoot.isChecked()+":"+m+":"+(periodBar.getProgress()+2);optionsBusy=true;optionsEnabled(false);updateButtons();new Thread(new Runnable(){public void run(){String error=null;try{Root.call(MainActivity.this,action);}catch(Exception e){error=e.getMessage();}final String failure=error;ui.post(new Runnable(){public void run(){optionsBusy=false;refreshCurrentPanel(generation);if((screen==2||screen==3)&&generation==panelGeneration){if(failure!=null){status.setVisibility(View.VISIBLE);status.setText(failure);}refreshDiagnostics();}}});}}).start();}
 void refreshCurrentPanel(int completedGeneration){if((screen==2||screen==3)&&completedGeneration!=panelGeneration){updateButtons();optionsEnabled(!busy&&!optionsBusy&&moduleEnabled!=null);refreshDiagnostics();}}
 void updateButtons(){boolean known=moduleEnabled!=null;styleButton(enableButton,!busy&&!optionsBusy&&known&&!moduleEnabled.booleanValue());styleButton(disableButton,!busy&&!optionsBusy&&known&&moduleEnabled.booleanValue());}
 void styleButton(TextView button,boolean enabled){if(button==null)return;button.setEnabled(enabled);button.setTextColor(enabled?0xffffffff:0xff66666e);button.setBackgroundColor(enabled?0xff262630:0xff17171c);button.setAlpha(enabled?1f:.65f);}
 void refreshDiagnostics(){final String target=module;final int generation=panelGeneration;final TextView output=diagnostic;new Thread(new Runnable(){public void run(){String r;Boolean enabled=null;try{r=Root.call(MainActivity.this,target+"-diag");if(r.startsWith("STATE_ENABLED=")){int n=r.indexOf('\n');String state=n<0?r:r.substring(0,n);enabled=Boolean.valueOf(state.endsWith("true"));r=n<0?"":r.substring(n+1);}}catch(Exception e){r="\u8a3a\u65b7\u8b80\u53d6\u5931\u6557："+e.getMessage();}String settings=null;if(r.startsWith("OPTIONS=")){int n=r.indexOf('\n');settings=n<0?r.substring(8):r.substring(8,n);r=n<0?"":r.substring(n+1);}final String config=settings;final String value=r;final Boolean state=enabled;ui.post(new Runnable(){public void run(){if((screen==2||screen==3)&&generation==panelGeneration){output.setText(value);moduleEnabled=state;updateButtons();if(config!=null)bindOptions(config);}}});}}).start();}
 void act(final String action){final String target=module;final int generation=panelGeneration;final TextView messageView=status;busy=true;optionsEnabled(false);updateButtons();messageView.setVisibility(View.VISIBLE);messageView.setText("\u8655\u7406\u4e2d…");new Thread(new Runnable(){public void run(){String result;boolean success;try{result=Root.call(MainActivity.this,target+"-"+action);success=true;}catch(Exception e){result=e.getMessage();success=false;}final String value=result;final boolean ok=success;ui.post(new Runnable(){public void run(){busy=false;refreshCurrentPanel(generation);if(target.equals("pad")&&ok){if(action.equals("enable")){prefs.edit().putBoolean("knob_enabled",true).commit();startService(new Intent(MainActivity.this,KnobService.class));}else if(action.equals("disable"))prefs.edit().putBoolean("knob_enabled",false).commit();}if((screen==2||screen==3)&&generation==panelGeneration){messageView.setText(value);messageView.setVisibility(ok?View.GONE:View.VISIBLE);refreshDiagnostics();}}});}}).start();}
 void message(String title,String s){new AlertDialog.Builder(this).setTitle(title).setMessage(s).setPositiveButton("\u95dc\u9589",null).show();}
