  protected void onDraw(Canvas c){scale=getWidth()/1920f;c.drawColor(0xff101012);for(int pg=Math.max(0,page-1);pg<=Math.min(pages()-1,page+1);pg++){float shift=(pg-page)*getWidth()+offset;for(int i=pg*12;i<Math.min(items.size(),pg*12+12);i++)if(i!=drag)tile(c,i,shift,false);}if(drag>=0)tile(c,drag,0,true);}
